fn shared_finish_inductive(pre: Self, post: Self, r: int) {
    broadcast use group_multiset_axioms;
    let t = pre.storage->0;
    assert forall |x: (int, T)|
        Self::filter_r(post.shared_guard, r).count(x) ==
            Self::filter_r(pre.shared_guard, r).add(Multiset::singleton((r, t))).count(x) by {
        axiom_filter_count(post.shared_guard, |val: (int, T)| val.0 == r, x);
        axiom_filter_count(pre.shared_guard, |val: (int, T)| val.0 == r, x);
        axiom_multiset_add(Self::filter_r(pre.shared_guard, r), Multiset::singleton((r, t)), x);
        axiom_multiset_singleton((r, t));
        axiom_multiset_singleton_different((r, t), x);
    };
    axiom_multiset_ext_equal(Self::filter_r(post.shared_guard, r),
        Self::filter_r(pre.shared_guard, r).add(Multiset::singleton((r, t))));
    axiom_len_add(Self::filter_r(pre.shared_guard, r), Multiset::singleton((r, t)));
    axiom_len_singleton((r, t));
    assert forall |q: int| 0 <= q < pre.rc_width implies
        post.ref_counts.index(q) == post.shared_pending.count(q) as int +
            Self::filter_r(post.shared_guard, q).len() as int by {
        if q == r {
            axiom_multiset_sub(pre.shared_pending, Multiset::singleton(r), q);
            axiom_multiset_singleton(r);
            assert(post.shared_pending.count(q) as int == pre.shared_pending.count(q) as int - 1);
        } else {
            axiom_multiset_sub(pre.shared_pending, Multiset::singleton(r), q);
            axiom_multiset_singleton_different(r, q);
            assert(post.shared_pending.count(q) == pre.shared_pending.count(q));
        }
    };
}

#[inductive(shared_release)]
fn shared_release_inductive(pre: Self, post: Self, val: (int, T)) {
    broadcast use group_multiset_axioms;
    let r = val.0;
    let t = val.1;
    assert forall |x: (int, T)|
        Self::filter_r(post.shared_guard, r).count(x) ==
            Self::filter_r(pre.shared_guard, r).sub(Multiset::singleton(val)).count(x) by {
        axiom_filter_count(post.shared_guard, |v: (int, T)| v.0 == r, x);
        axiom_filter_count(pre.shared_guard, |v: (int, T)| v.0 == r, x);
        axiom_multiset_sub(Self::filter_r(pre.shared_guard, r), Multiset::singleton(val), x);
        axiom_multiset_singleton(val);
        axiom_multiset_singleton_different(val, x);
    };
    axiom_multiset_ext_equal(Self::filter_r(post.shared_guard, r),
        Self::filter_r(pre.shared_guard, r).sub(Multiset::singleton(val)));
    assert forall |q: int| 0 <= q < pre.rc_width implies
        post.ref_counts.index(q) == post.shared_pending.count(q) as int +
            Self::filter_r(post.shared_guard, q).len() as int by {
        if q == r {
            axiom_multiset_sub(pre.ref_counts, Multiset::singleton(r), q);
            axiom_multiset_singleton(r);
            axiom_multiset_sub(Self::filter_r(pre.shared_guard, r), Multiset::singleton(val), val);
            axiom_len_sub(Self::filter_r(pre.shared_guard, r), Multiset::singleton(val));
            axiom_len_singleton(val);
        } else {
            axiom_multiset_singleton_different(r, q);
            axiom_multiset_sub(pre.ref_counts, Multiset::singleton(r), q);
        }
    };
}

