    axiom_multiset_sub(Self::filter_r(pre.shared_guard, r), Multiset::singleton(val), val);
    axiom_len_sub(Self::filter_r(pre.shared_guard, r), Multiset::singleton(val));
    axiom_len_singleton(val);
    assert(post.ref_counts.index(q) == pre.ref_counts.index(q) - 1);
    assert(post.shared_pending.count(q) == pre.shared_pending.count(q));
} else {
    assert(pre.ref_counts.index(q) == pre.shared_pending.count(q) as int +
        Self::filter_r(pre.shared_guard, q).len() as int);
    axiom_multiset_singleton_different(r, q);
    assert(post.ref_counts.index(q) == pre.ref_counts.index(q));
    assert(post.shared_pending.count(q) == pre.shared_pending.count(q));
    assert forall |x: (int, T)| Self::filter_r(post.shared_guard, q).count(x) ==
        Self::filter_r(pre.shared_guard, q).count(x) by {
        axiom_filter_count(post.shared_guard, |v: (int, T)| v.0 == q, x);
        axiom_filter_count(pre.shared_guard, |v: (int, T)| v.0 == q, x);
    };
    axiom_multiset_ext_equal(Self::filter_r(post.shared_guard, q),
        Self::filter_r(pre.shared_guard, q));
    assert(Self::filter_r(post.shared_guard, q).len() ==
        Self::filter_r(pre.shared_guard, q).len());
}

